# Builds src/inspiration4.js from the NASA OSDR Inspiration4 blood tables (OSD-575 CMP, OSD-569 CBC).
# Code generated by Claude (Anthropic), an AI system. Data: NASA Open Science Data Repository.
import csv, json, sys, pathlib
sys.stdout.reconfigure(encoding="utf-8")
SRC = pathlib.Path(r"C:/dev/spaceapps-2026/data/osdr")
OUT = pathlib.Path(r"C:/dev/spaceapps-2026/app/src/inspiration4.js")
NAMES = {  # plain English names, put together by Claude
    "GLUCOSE": "Glucose", "UREA NITROGEN (BUN)": "Urea nitrogen (BUN)", "CREATININE": "Creatinine",
    "SODIUM": "Sodium", "POTASSIUM": "Potassium", "CHLORIDE": "Chloride", "CARBON DIOXIDE": "Carbon dioxide (bicarbonate)",
    "CALCIUM": "Calcium", "PROTEIN; TOTAL": "Total protein", "ALBUMIN": "Albumin", "GLOBULIN": "Globulin",
    "ALBUMIN/GLOBULIN RATIO": "Albumin/globulin ratio", "BILIRUBIN; TOTAL": "Total bilirubin",
    "ALKALINE PHOSPHATASE": "Alkaline phosphatase", "AST": "AST (liver enzyme)", "ALT": "ALT (liver enzyme)",
    "BUN/CREATININE RATIO": "BUN/creatinine ratio",
    "WHITE BLOOD CELL COUNT": "White blood cells", "RED BLOOD CELL COUNT": "Red blood cells", "HEMOGLOBIN": "Hemoglobin",
    "HEMATOCRIT": "Hematocrit", "MCV": "Mean red cell volume (MCV)", "MCH": "Hemoglobin per red cell (MCH)",
    "MCHC": "Hemoglobin concentration in red cells (MCHC)", "RDW": "Red cell size spread (RDW)",
    "PLATELET COUNT": "Platelets", "MPV": "Mean platelet volume (MPV)",
    "ABSOLUTE NEUTROPHILS": "Neutrophils, cells/uL", "ABSOLUTE LYMPHOCYTES": "Lymphocytes, cells/uL",
    "ABSOLUTE MONOCYTES": "Monocytes, cells/uL", "ABSOLUTE EOSINOPHILS": "Eosinophils, cells/uL",
    "ABSOLUTE BASOPHILS": "Basophils, cells/uL", "NEUTROPHILS": "Neutrophils, %", "LYMPHOCYTES": "Lymphocytes, %",
    "MONOCYTES": "Monocytes, %", "EOSINOPHILS": "Eosinophils, %", "BASOPHILS": "Basophils, %",
}
SKIP = {"eGFR NON-AFR. AMERICAN", "eGFR AFRICAN AMERICAN"}  # race-based eGFR rows are left out
def num(x):
    try:
        return float(x)
    except (TypeError, ValueError):
        return None
subjects = {}
dropped = []
for fn, tp_col, test in (("LSDS-8_Comprehensive_Metabolic_Panel_CMP.upload_SUBMITTED.csv", "timepoint", "CMP"),
                         ("LSDS-7_Complete_Blood_Count_CBC.upload_SUBMITTED.csv", "TEST_DATE", "CBC")):
    for r in csv.DictReader(open(SRC / fn, encoding="utf-8-sig")):
        analyte = r["ANALYTE"].strip()
        if analyte in SKIP:
            continue
        female_variant = analyte.endswith("(FEMALE)")
        base = analyte.replace(" (FEMALE)", "")
        sex = r["SEX"].strip()
        # Keep the lab's female ranges for women and the general rows for men.
        if female_variant and sex != "F":
            continue
        subj = subjects.setdefault(r["SUBJECT_ID"], {"sex": sex, "panels": {}})
        tp = r[tp_col].strip()
        panel = subj["panels"].setdefault(tp, {})
        value = num(r["VALUE"])
        if value is None:
            dropped.append((r["SUBJECT_ID"], tp, base, r["VALUE"]))
            continue
        if base in panel and not female_variant:
            continue  # a female-specific row already set it
        panel[base] = {
            "code": base, "name": NAMES.get(base, base), "test": test, "value": value,
            "min": num(r["RANGE_MIN"]), "max": num(r["RANGE_MAX"]), "units": r["UNITS"].strip(),
        }
TIMEPOINTS = ["L-92", "L-44", "L-3", "R+1", "R+45", "R+82", "R+194"]
out = {
    "source": {
        "name": "NASA OSDR, the Inspiration4 mission (2021): OSD-575 (blood chemistry) and OSD-569 (complete blood count)",
        "urls": ["https://osdr.nasa.gov/bio/repo/data/studies/OSD-575", "https://osdr.nasa.gov/bio/repo/data/studies/OSD-569"],
        "note": "Real de-identified data of the four crew members. Reference ranges come from the same tables (lab ranges). eGFR rows split by race are not included.",
    },
    "timepoints": TIMEPOINTS,
    "subjects": {k: {"sex": v["sex"], "panels": {tp: list(v["panels"].get(tp, {}).values()) for tp in TIMEPOINTS if tp in v["panels"]}}
                 for k, v in sorted(subjects.items())},
}
OUT.write_text(
    "// Inspiration4 crew blood tests (real, de-identified), built by tools/build_inspiration4.py from NASA OSDR.\n"
    "// Code generated by Claude (Anthropic), an AI system. Data: NASA Open Science Data Repository, OSD-575 and OSD-569.\n"
    "export const INSPIRATION4 = " + json.dumps(out, ensure_ascii=False, separators=(",", ":")) + ";\n",
    encoding="utf-8",
)
counts = {k: {tp: len(p) for tp, p in v["panels"].items()} for k, v in out["subjects"].items()}
print("written", OUT, OUT.stat().st_size, "bytes")
print("analytes per subject/timepoint:", counts)
print("dropped non-numeric values:", len(dropped), dropped[:5])
